const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={done:[],journal:''};try{const revised=localStorage.getItem('objectlab-ts-v2');const saved=JSON.parse(revised||localStorage.getItem('objectlab-v1'));if(saved&&!revised)saved.done=[];if(saved&&Array.isArray(saved.done)&&typeof saved.journal==='string')state={done:saved.done.filter(w=>LESSONS.some(l=>!l.exam&&l.week===w)),journal:saved.journal};}catch{}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function save(){try{localStorage.setItem('objectlab-ts-v2',JSON.stringify(state));return true}catch{toast('บันทึกไม่สำเร็จ กรุณาส่งออกข้อมูลเก็บไว้');return false}}
function progress(){const n=new Set(state.done).size;$('#progress-text').textContent=`${n} / 15 บทเรียน`;$('#progress').value=n}
function card(l){return `<a class="card" href="#week-${l.week}"><span class="week">${l.exam?'ASSESSMENT':'WEEK '+String(l.week).padStart(2,'0')}</span><h3>${esc(l.title)}</h3><p>${esc(l.subtitle)}</p><div class="bottom"><span>${l.exam?'สอบรายบุคคล':l.clo}</span><span>${state.done.includes(l.week)?'✓ เรียนแล้ว':l.exam?l.weight+'%':'เข้าเรียน ↗'}</span></div></a>`}
function render(){const route=location.hash.slice(1)||'home';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+(route.startsWith('week-')?'lessons':route)));progress();const main=$('#main');
if(route==='home'){
const next=LESSONS.find(l=>!l.exam&&!state.done.includes(l.week))||LESSONS[0];
main.innerHTML=`<section class="hero"><div><span class="eyebrow">Object Oriented Programming</span><h1>ออกแบบและพัฒนา<br>โปรแกรมเชิงวัตถุ</h1><p class="muted">ออกแบบและพัฒนาโปรแกรมเชิงวัตถุด้วย TypeScript ที่ทดสอบได้ เชื่อมกฎธุรกิจกับ NestJS API และ React Function Components ในระดับพื้นฐาน ใช้ AI อย่างมีวิจารณญาณ</p><div class="actions"><a class="button" href="#week-${next.week}">${state.done.length?'เรียนต่อ':'เริ่มเรียน'} · สัปดาห์ ${next.week} →</a><a class="button secondary" href="#lessons">ดูทุกบทเรียน</a></div></div><div class="code-art"><div class="dots">● ● ● <span style="float:right;letter-spacing:0;font-size:12px">Equipment.ts</span></div><pre>class Equipment {\n    #borrowed = false;\n    borrow(): void {\n        if (this.#borrowed) {\n            throw new Error("ยืมซ้ำไม่ได้");\n        }\n        this.#borrowed = true;\n    }\n}</pre><span class="pill" style="color:#17372f">คิด → เขียน → ทดสอบ → อธิบาย</span></div></section><div class="stats"><div class="stat"><strong>15</strong><small>สัปดาห์การเรียนรู้ + 2 สัปดาห์สอบ</small></div><div class="stat"><strong>3(2-2-5)</strong><small>หน่วยกิต · นักศึกษาชั้นปีที่ 2</small></div><div class="stat"><strong>30 / 30</strong><small>ชั่วโมงทฤษฎี / ปฏิบัติ</small></div><div class="stat"><strong>75</strong><small>ชั่วโมงศึกษาด้วยตนเอง</small></div></div><div class="section-top"><h2>เส้นทางจากพื้นฐานสู่การสร้างระบบ</h2><a href="#lessons">ดูทั้งหมด 17 สัปดาห์ →</a></div><div class="grid">${[LESSONS[0],LESSONS[5],LESSONS[13]].map(card).join('')}</div><div class="notice"><strong>AI เป็นผู้ช่วยเรียนรู้</strong><br>ลองทำก่อน ขอคำใบ้ ทดสอบคำตอบ และบันทึกสิ่งที่ใช้ ไม่ใช้ AI ในการสอบและการตอบคำถามสดรายบุคคล</div><div class="panel"><h3>แหล่งเรียนรู้อ้างอิง</h3><a class="resource" href="https://www.typescriptlang.org/docs/handbook/" target="_blank" rel="noopener">TypeScript Handbook ↗</a><a class="resource" href="https://docs.nestjs.com/" target="_blank" rel="noopener">NestJS · API และ Dependency Injection ↗</a><a class="resource" href="https://react.dev/learn" target="_blank" rel="noopener">React · Function Components ↗</a><a class="resource" href="https://nodejs.org/api/test.html" target="_blank" rel="noopener">Node.js · Test runner ↗</a><a class="resource" href="oop-typescript-starter.zip" download>ดาวน์โหลดโค้ด TypeScript และชุดทดสอบ (.zip)</a><a class="resource" href="teaching-guide.md" download>ดาวน์โหลดเอกสารการสอนฉบับปรับปรุง (.md)</a><a class="resource" href="tqf3-typescript-2569.docx" download>ดาวน์โหลด มคอ.3 ฉบับ TypeScript และ AI (.docx)</a><a class="resource" href="tqf3-typescript-2569.pdf" target="_blank" rel="noopener">เปิด มคอ.3 ฉบับ PDF ↗</a></div>`;
}else if(route==='lessons'){
 main.innerHTML=`<span class="eyebrow">Learning path</span><h1>บทเรียนรายสัปดาห์</h1><p class="muted">เรียนรู้ 10 บท · 15 สัปดาห์การสอน · ฝึกปฏิบัติสัปดาห์ละ 2 ชั่วโมง</p><div class="section-top"><div class="steps"><span>01–07 พื้นฐานและคลาส</span><span>09–14 ออกแบบและพัฒนา</span><span>15–16 โครงงาน</span></div><input id="search" type="search" aria-label="ค้นหาบทเรียน" placeholder="ค้นหาเนื้อหา เช่น Interface"></div><div id="lesson-grid" class="grid" style="margin-top:24px"></div>`;
 const list=()=>{const q=$('#search').value.trim().toLowerCase();const found=LESSONS.filter(l=>`${l.week} ${l.title} ${l.subtitle} ${l.clo}`.toLowerCase().includes(q));$('#lesson-grid').innerHTML=found.length?found.map(card).join(''):'<p class="empty">ไม่พบบทเรียน ลองใช้คำค้นอื่น</p>'};$('#search').addEventListener('input',list);list();
}else if(route.startsWith('week-')){
 const l=LESSONS.find(x=>x.week===Number(route.slice(5)));if(!l){main.innerHTML='<h1>ไม่พบบทเรียน</h1><a href="#lessons">กลับไปบทเรียน</a>';return;}
 main.innerHTML=`<a href="#lessons">← บทเรียนทั้งหมด</a><p class="eyebrow">WEEK ${l.week} / 17</p><h1>${esc(l.title)}</h1><p class="muted">${esc(l.subtitle)}</p><span class="pill">${l.clo}</span> `+(l.exam?`<div class="panel"><h2>การสอบในชั้นเรียน · ${l.weight}%</h2><p>${esc(l.subtitle)}</p><p>สอบรายบุคคลโดยไม่ใช้ AI วัน เวลา สถานที่และรูปแบบข้อสอบให้ยึดประกาศของผู้สอน</p><div class="notice">หน้าเว็บนี้ไม่มีข้อสอบจริงและไม่บันทึกคะแนนส่งผู้สอน ชั่วโมงสอนและ SDL ของสัปดาห์สอบไม่นับรวมในแผน</div></div>`:`<span class="pill">ทฤษฎี 2 ชม. · ปฏิบัติ 2 ชม. · SDL 5 ชม.</span><div class="notice"><strong>เมื่อเรียนจบ คุณจะสามารถ</strong><br>${esc(l.goal)}</div><section class="panel"><h2>ทำความเข้าใจแนวคิด</h2>${l.body.map(p=>`<p>${esc(p)}</p>`).join('')}<div class="code-top"><h3>ตัวอย่างสำหรับศึกษา</h3><button id="copy-code" class="secondary">คัดลอกโค้ด</button></div><pre><code>${esc(l.code)}</code></pre><small class="muted">ตัวอย่างเป็น TypeScript บางส่วน ต้องใช้โปรเจกต์และ dependencies ตามบริบท · เว็บบทเรียนนี้ไม่รัน Backend หรือฐานข้อมูล</small></section><div class="two"><section class="panel"><span class="eyebrow">Practice</span><h2>ลงมือทำด้วยตนเอง</h2><p>${esc(l.lab)}</p><h3>หลักฐานการเรียนรู้</h3><p>${esc(l.evidence)}</p></section><section class="panel"><span class="eyebrow">AI learning companion</span><h2>ใช้ AI เพื่อขยายความเข้าใจ</h2><p>${esc(l.ai)}</p><button id="copy-prompt" class="secondary">คัดลอกคำถามสำหรับ AI</button><p class="muted">แนบเฉพาะโค้ดตัวอย่างที่ไม่มีข้อมูลส่วนบุคคลหรือข้อมูลลับ ตรวจคำตอบด้วยเอกสารและผลทดสอบก่อนใช้</p><a href="#journal">บันทึกสิ่งที่เรียนรู้จาก AI →</a></section></div><section class="panel quiz"><span class="eyebrow">Self-check · ไม่คิดคะแนนรายวิชา</span><h2>ตรวจความเข้าใจ</h2><form id="quiz"><p>${esc(l.question)}</p>${l.options.map((o,i)=>`<label><input type="radio" name="answer" value="${i}" required>${esc(o)}</label>`).join('')}<button type="submit">ตรวจคำตอบ</button><div class="feedback" id="feedback" role="status"></div></form></section><div class="actions"><button id="done">${state.done.includes(l.week)?'✓ เรียนแล้ว · ยกเลิกเครื่องหมาย':'ทำเครื่องหมายว่าเรียนแล้ว'}</button></div>`)+`<div class="actions">${l.week>1?`<a class="button secondary" href="#week-${l.week-1}">← สัปดาห์ก่อนหน้า</a>`:''}${l.week<17?`<a class="button secondary" href="#week-${l.week+1}">สัปดาห์ถัดไป →</a>`:''}</div>`;
 if(!l.exam){$('#copy-code').onclick=()=>copy(l.code);$('#copy-prompt').onclick=()=>copy(l.ai);$('#quiz').onsubmit=e=>{e.preventDefault();const answer=Number(new FormData(e.target).get('answer'));$('#feedback').textContent=(answer===l.answer?'✓ ถูกต้อง — ':'ลองทบทวนอีกครั้ง — ')+l.explain};$('#done').onclick=()=>{state.done=state.done.includes(l.week)?state.done.filter(w=>w!==l.week):[...state.done,l.week];save();render()}}
}else if(route==='project'){
 main.innerHTML=`<span class="eyebrow">Semester project</span><h1>สร้างระบบที่แก้ปัญหาได้จริง</h1><p class="muted">ระบบยืม–คืนอุปกรณ์ด้วย TypeScript · กลุ่มไม่เกิน 3 คน</p><div class="two"><div class="panel"><h2>ข้อกำหนดขั้นต่ำ</h2><ul><li>มีอย่างน้อย 3 คลาสที่มีหน้าที่ชัดเจน</li><li>ใช้ Encapsulation และ Interface หรือ Polymorphism อย่างมีเหตุผล</li><li>ใช้ Collection จัดการข้อมูล</li><li>มี React Function Component เรียก NestJS API และตรวจข้อมูลที่ Backend</li><li>มีชุดทดสอบและคู่มือรันโปรแกรม</li><li>เปิดเผยการใช้ AI และหลักฐานงานรายบุคคล</li></ul><p>ใช้ API บนเครื่องเรียนและ repository ในหน่วยความจำ ไม่บังคับฐานข้อมูลจริง; เว็บบทเรียนเป็น static</p></div><div class="panel"><h2>จุดตรวจระหว่างทาง</h2><p><strong>สัปดาห์ 7</strong> · โจทย์ ขอบเขต และแผนภาพคลาส</p><p><strong>สัปดาห์ 13</strong> · โค้ดส่วนหลักและหลักฐานทดสอบ</p><p><strong>สัปดาห์ 15</strong> · รวมระบบ ตรวจโค้ด และคู่มือ</p><p><strong>สัปดาห์ 16</strong> · สาธิต ส่งมอบ และตอบคำถามรายบุคคลโดยไม่ใช้ AI</p></div></div><div class="panel"><h2>เกณฑ์คะแนนโครงงาน 10 คะแนน</h2><table><tr><th>ส่วนงาน</th><th>คะแนน</th></tr><tr><td>ผลงานและรายงาน: ออกแบบ 2 / โค้ด 2 / ทดสอบ 1 / จริยธรรม 1</td><td>6</td></tr><tr><td>รายบุคคล: โค้ด 1 / ทดสอบ 1 / การสื่อสาร 2</td><td>4</td></tr></table></div>`;
}else if(route==='assessment'){
 const matrix=[[2,0,0,4,8,0,0],[2,2,2,2,4,4,0],[3,4,3,3,6,16,0],[2,3,2,1,2,8,0],[0,1,2,0,0,2,3],[1,0,1,0,0,0,7]];
 main.innerHTML=`<span class="eyebrow">Assessment</span><h1>เรียนรู้อย่างมีเป้าหมาย</h1><p class="muted">สัดส่วนคะแนนตาม มคอ.3 ฉบับปรับปรุง · รวม 100%</p><div class="panel"><table><tr><th>วิธีประเมิน</th><th>น้ำหนัก</th><th>ช่วงประเมิน</th></tr>${[['แบบฝึกหัด',10,'ตลอดภาค'],['การปฏิบัติการ',10,'ตลอดภาค'],['โครงงาน',10,'สัปดาห์ 16'],['การทดสอบย่อย',10,'สัปดาห์ 3, 7, 12'],['การสอบกลางภาค',20,'สัปดาห์ 8'],['การสอบปลายภาค',30,'สัปดาห์ 17'],['จริยธรรมและความรับผิดชอบ',10,'ตลอดภาค']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}%</td><td>${r[2]}</td></tr>`).join('')}</table></div><div class="panel"><h2>ผลลัพธ์การเรียนรู้</h2><ol>${['อธิบายหลักการเชิงวัตถุและวิเคราะห์การทำงานของ TypeScript/JavaScript','วิเคราะห์โจทย์ธุรกิจและออกแบบคลาส','พัฒนาโปรแกรมเชิงวัตถุด้วย TypeScript และเชื่อม API กับส่วนติดต่อผู้ใช้แบบฟังก์ชัน','ออกแบบการทดสอบ แก้ข้อผิดพลาด และตรวจข้อเสนอ AI','อธิบายผลงานและสื่อสารร่วมกับผู้อื่น','ทำงานอย่างซื่อสัตย์ เปิดเผยการใช้ AI และปกป้องข้อมูล'].map((s,i)=>`<li><strong>CLO${i+1}</strong> ${s} <span class="pill">${matrix[i].reduce((a,b)=>a+b,0)}%</span></li>`).join('')}</ol></div><div class="notice">การทดสอบย่อยและการสอบจริงไม่ใช้ AI แบบทดสอบทบทวนบนเว็บไม่ใช่คะแนนทางการ เกณฑ์ระดับผลการเรียนและกำหนดสอบยึดประกาศของผู้สอน</div>`;
}else if(route==='journal'){
 main.innerHTML=`<span class="eyebrow">Learning journal</span><h1>บันทึกการใช้ AI</h1><p class="muted">เก็บหลักฐานการคิด ตรวจสอบ และปรับปรุงงานของคุณ</p><div class="notice">บันทึกอยู่เฉพาะเบราว์เซอร์นี้ ไม่ส่งถึงผู้สอนหรือบริการ AI ควรส่งออกเก็บไว้ก่อนเปลี่ยนเครื่องหรือล้างข้อมูล</div><div class="panel"><label for="journal-text"><strong>สิ่งที่เรียนรู้และตรวจสอบ</strong></label><p class="muted">ระบุสัปดาห์ งานที่ทำ เครื่องมือ/วันที่ คำถาม คำแนะนำที่ได้รับ วิธีทดสอบ สิ่งที่แก้ไข และข้อสรุปของตนเอง</p><textarea id="journal-text" rows="12" placeholder="สัปดาห์ที่…\nงานที่ทำ…\nคำถามที่ส่งให้ AI…\nสิ่งที่ตรวจพบและหลักฐานทดสอบ…">${esc(state.journal)}</textarea><div class="actions"><button id="save-journal">บันทึก</button><button id="export" class="secondary">ส่งออกบันทึก (.txt)</button></div><p id="save-status" role="status"></p></div>`;
 $('#save-journal').onclick=()=>{state.journal=$('#journal-text').value;if(save())$('#save-status').textContent='✓ บันทึกในเบราว์เซอร์แล้ว'};$('#journal-text').oninput=()=>{state.journal=$('#journal-text').value;save();$('#save-status').textContent='บันทึกอัตโนมัติในเบราว์เซอร์'};$('#export').onclick=()=>{const content=`Object Lab — บันทึกการเรียนรู้\nสัปดาห์ที่ทำเครื่องหมายเรียนแล้ว: ${state.done.join(', ')||'-'}\n\n${$('#journal-text').value}`;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='oop-ai-journal.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
}else{main.innerHTML='<h1>ไม่พบหน้าที่ต้องการ</h1><a href="#home">กลับหน้าหลัก</a>'}
}
async function copy(t){try{await navigator.clipboard.writeText(t);toast('คัดลอกแล้ว')}catch{toast('คัดลอกอัตโนมัติไม่ได้ กรุณาเลือกข้อความแล้วคัดลอก')}}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true})});render();
